"""One-host SQLite state: retained sources/configurations, claims and results.

Completed attempts are immutable. Current pointers are separate from history;
pending claims never impersonate a completed result. Provider I/O occurs outside
transactions. Queued claims acquire a lease only when a worker starts them.
"""
from contextlib import contextmanager
from dataclasses import asdict, dataclass
import hashlib
import json
import math
from pathlib import Path
import sqlite3
import time
from typing import Any, Callable, Iterable
from uuid import uuid4

from jsonschema import Draft202012Validator

from . import prompts, review
from .extraction import ExtractionError, ExtractionRecord, SourceExport, decode_export, extract_source
from .processing import _failure
from .providers import Provider


def _json(value: Any) -> str:
    return json.dumps(value, sort_keys=True, ensure_ascii=False, allow_nan=False)


def _hash(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


@dataclass(frozen=True)
class ProcessingConfig:
    """Immutable JSON snapshot; accessors return fresh, caller-owned values."""
    _snapshot_json: str

    @classmethod
    def capture(cls, *, provider: Provider, policy_path: Path) -> "ProcessingConfig":
        if provider.provider_kind == "http":
            assets = provider.extraction_assets()
        elif provider.provider_kind == "mock":
            assets = {
                "model_configuration": {
                    "provider": "mock", "model": "scripted-fixtures",
                    "generation": {}, "prompt_version": prompts.PROMPT_VERSION,
                },
                "prompt_text": prompts.PROMPT_PATH.read_bytes().decode("utf-8"),
                "schema_text": prompts.SCHEMA_PATH.read_bytes().decode("utf-8"),
            }
        else:
            raise ValueError("Unsupported provider kind for configuration capture")
        data = dict(assets, provider_kind=provider.provider_kind)
        data["policy_text"] = Path(policy_path).read_bytes().decode("utf-8")
        review.ReviewPolicy.from_text(data["policy_text"])
        Draft202012Validator.check_schema(json.loads(data["schema_text"]))
        for name in ("prompt", "schema", "policy"):
            data[name + "_sha256"] = _hash(data[name + "_text"].encode("utf-8"))
        extraction_identity = {key: data[key] for key in (
            "provider_kind", "model_configuration", "prompt_sha256", "schema_sha256",
        )}
        data["extraction_fingerprint"] = _hash(_json(extraction_identity).encode("utf-8"))
        data["processing_fingerprint"] = _hash(_json({
            "extraction_fingerprint": data["extraction_fingerprint"],
            "policy_sha256": data["policy_sha256"],
        }).encode("utf-8"))
        return cls(_json(data))

    def snapshot(self) -> dict[str, Any]:
        return json.loads(self._snapshot_json)

    @property
    def model_configuration(self) -> dict[str, Any]:
        return self.snapshot()["model_configuration"]

    @property
    def extraction_fingerprint(self) -> str:
        return self.snapshot()["extraction_fingerprint"]

    @property
    def processing_fingerprint(self) -> str:
        return self.snapshot()["processing_fingerprint"]

    @property
    def prompt_sha256(self) -> str:
        return self.snapshot()["prompt_sha256"]

    @property
    def schema_sha256(self) -> str:
        return self.snapshot()["schema_sha256"]

    @property
    def policy_sha256(self) -> str:
        return self.snapshot()["policy_sha256"]


class ClaimBusy(Exception):
    def __init__(self, claim: dict[str, Any]):
        super().__init__("This source/configuration already has an active claim")
        self.claim = claim


class StaleClaimError(Exception):
    """A lost/expired claim cannot publish a result."""


_SCHEMA = """
CREATE TABLE IF NOT EXISTS sources (
    ingestion_sequence INTEGER PRIMARY KEY AUTOINCREMENT,
    document_id TEXT NOT NULL,
    revision INTEGER NOT NULL,
    source_sha256 TEXT NOT NULL,
    original_bytes BLOB NOT NULL,
    UNIQUE(document_id, revision)
);
CREATE TABLE IF NOT EXISTS configurations (
    processing_fingerprint TEXT PRIMARY KEY,
    snapshot_json TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS attempts (
    sequence INTEGER PRIMARY KEY AUTOINCREMENT,
    attempt_id TEXT NOT NULL UNIQUE,
    document_id TEXT NOT NULL,
    source_sequence INTEGER NOT NULL REFERENCES sources(ingestion_sequence),
    config_fingerprint TEXT NOT NULL REFERENCES configurations(processing_fingerprint),
    state TEXT NOT NULL CHECK(state IN ('pending', 'completed', 'abandoned')),
    lease_owner TEXT NOT NULL,
    lease_expires_at REAL NOT NULL,
    fencing_token INTEGER NOT NULL,
    claim_json TEXT NOT NULL,
    result_json TEXT,
    raw_extraction_json TEXT
);
CREATE TABLE IF NOT EXISTS documents (
    document_id TEXT PRIMARY KEY,
    source_sequence INTEGER NOT NULL REFERENCES sources(ingestion_sequence),
    latest_attempt_id TEXT REFERENCES attempts(attempt_id),
    current_attempt_id TEXT REFERENCES attempts(attempt_id)
);
CREATE TABLE IF NOT EXISTS attempt_events (
    sequence INTEGER PRIMARY KEY AUTOINCREMENT,
    attempt_id TEXT NOT NULL REFERENCES attempts(attempt_id),
    event TEXT NOT NULL,
    recorded_at REAL NOT NULL
);
CREATE INDEX IF NOT EXISTS attempts_document ON attempts(document_id, sequence);
CREATE INDEX IF NOT EXISTS attempts_pending ON attempts(state, sequence);
CREATE TRIGGER IF NOT EXISTS completed_attempt_immutable BEFORE UPDATE ON attempts
WHEN OLD.state = 'completed' BEGIN SELECT RAISE(ABORT, 'Completed attempts are immutable'); END;
CREATE TRIGGER IF NOT EXISTS attempts_retained BEFORE DELETE ON attempts
BEGIN SELECT RAISE(ABORT, 'Attempts must be retained'); END;
"""


class StateStore:
    def __init__(self, path: Path, *, clock: Callable[[], float] = time.time, initialize: bool = True):
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._clock = clock
        self._connection = sqlite3.connect(self.path, isolation_level=None, timeout=5)
        self._connection.row_factory = sqlite3.Row
        self._connection.execute("PRAGMA foreign_keys=ON")
        self._connection.execute("PRAGMA synchronous=FULL")
        if not initialize:
            return
        self._connection.execute("PRAGMA journal_mode=WAL")
        self._connection.executescript(_SCHEMA)
        for table in ("sources", "configurations", "attempt_events"):
            for action in ("UPDATE", "DELETE"):
                self._connection.execute(
                    f"CREATE TRIGGER IF NOT EXISTS {table}_no_{action.lower()} BEFORE {action} ON {table} "
                    "BEGIN SELECT RAISE(ABORT, 'Snapshots and events are immutable'); END"
                )

    def close(self) -> None:
        self._connection.close()

    def __enter__(self) -> "StateStore":
        return self

    def __exit__(self, *args) -> None:
        self.close()

    @contextmanager
    def _transaction(self):
        self._connection.execute("BEGIN IMMEDIATE")
        try:
            yield self._connection
            self._connection.execute("COMMIT")
        except BaseException:
            self._connection.execute("ROLLBACK")
            raise

    def _attempt(self, attempt_id: str) -> sqlite3.Row:
        row = self._connection.execute("SELECT * FROM attempts WHERE attempt_id=?", (attempt_id,)).fetchone()
        if row is None:
            raise KeyError("Unknown attempt ID")
        return row

    def configuration(self, attempt_id: str) -> dict[str, Any]:
        row = self._connection.execute(
            "SELECT c.snapshot_json FROM attempts a JOIN configurations c "
            "ON c.processing_fingerprint=a.config_fingerprint WHERE a.attempt_id=?", (attempt_id,),
        ).fetchone()
        if row is None:
            raise KeyError("Unknown attempt ID")
        return json.loads(row["snapshot_json"])

    def _source_row(self, attempt_id: str) -> sqlite3.Row:
        row = self._connection.execute(
            "SELECT s.* FROM sources s JOIN attempts a ON a.source_sequence=s.ingestion_sequence "
            "WHERE a.attempt_id=?", (attempt_id,),
        ).fetchone()
        if row is None:
            raise KeyError("Unknown attempt ID")
        return row

    def source(self, attempt_id: str) -> SourceExport:
        row = self._source_row(attempt_id)
        return decode_export(row["original_bytes"], document_id=row["document_id"])

    def current(self) -> list[dict[str, Any]]:
        rows = self._connection.execute(
            "SELECT a.result_json FROM documents d JOIN attempts a ON a.attempt_id=d.current_attempt_id "
            "WHERE a.state='completed' ORDER BY d.document_id"
        ).fetchall()
        return [json.loads(row["result_json"]) for row in rows]

    def history(self, document_id: str) -> list[dict[str, Any]]:
        rows = self._connection.execute(
            "SELECT result_json FROM attempts WHERE document_id=? AND state='completed' ORDER BY sequence",
            (document_id,),
        ).fetchall()
        return [json.loads(row["result_json"]) for row in rows]

    def pending(self) -> list[dict[str, Any]]:
        rows = self._connection.execute("SELECT claim_json FROM attempts WHERE state='pending' ORDER BY sequence").fetchall()
        return [json.loads(row["claim_json"]) for row in rows]

    def events(self, document_id: str) -> list[dict[str, Any]]:
        rows = self._connection.execute(
            "SELECT e.attempt_id,e.event,e.recorded_at FROM attempt_events e JOIN attempts a "
            "ON a.attempt_id=e.attempt_id WHERE a.document_id=? ORDER BY e.sequence", (document_id,),
        ).fetchall()
        return [dict(row) for row in rows]

    def claim(
        self, path: Path, *, config: ProcessingConfig, operator: str,
        lease_seconds: float = 300, force: bool = False, queued: bool = False,
    ) -> dict[str, Any]:
        """Atomically accept a source/configuration and reserve one attempt.

        Reusable successes are returned unchanged. Active duplicate claims raise
        ClaimBusy. Files must be readable to accept a source revision; malformed
        readable bytes can still produce a durable invalid-export result.
        """
        path = Path(path)
        return self._claim_bytes(
            path.read_bytes(), document_id=path.name, config=config, operator=operator,
            lease_seconds=lease_seconds, force=force, queued=queued,
        )

    def _claim_bytes(
        self, raw: bytes, *, document_id: str, config: ProcessingConfig, operator: str,
        lease_seconds: float, force: bool = False, queued: bool = False,
        expected_attempt_id: str | None = None,
    ) -> dict[str, Any]:
        if not isinstance(operator, str) or not operator.strip():
            raise ValueError("operator must identify the claimant")
        if not isinstance(lease_seconds, (int, float)) or not math.isfinite(lease_seconds) or lease_seconds <= 0:
            raise ValueError("lease_seconds must be finite and positive")
        source_hash = _hash(raw)
        snapshot = config.snapshot()
        now = self._clock()
        with self._transaction() as db:
            document = db.execute("SELECT * FROM documents WHERE document_id=?", (document_id,)).fetchone()
            if expected_attempt_id is not None and (document is None or document["latest_attempt_id"] != expected_attempt_id):
                raise StaleClaimError("A newer source or attempt superseded this recovery candidate")
            previous_source = None if document is None else db.execute(
                "SELECT * FROM sources WHERE ingestion_sequence=?", (document["source_sequence"],),
            ).fetchone()
            if previous_source is not None and previous_source["source_sha256"] == source_hash:
                source_sequence = previous_source["ingestion_sequence"]
                revision = previous_source["revision"]
            else:
                revision = 1 if previous_source is None else previous_source["revision"] + 1
                source_sequence = db.execute(
                    "INSERT INTO sources(document_id,revision,source_sha256,original_bytes) VALUES(?,?,?,?)",
                    (document_id, revision, source_hash, raw),
                ).lastrowid
            db.execute(
                "INSERT INTO configurations(processing_fingerprint,snapshot_json) VALUES(?,?) ON CONFLICT DO NOTHING",
                (config.processing_fingerprint, config._snapshot_json),
            )
            latest = None if document is None or document["latest_attempt_id"] is None else self._attempt(document["latest_attempt_id"])
            same_source = latest is not None and latest["source_sequence"] == source_sequence
            latest_result = None if latest is None or latest["state"] != "completed" else json.loads(latest["result_json"])
            latest_queued = latest is not None and latest["state"] == "pending" and json.loads(latest["claim_json"]).get("service_state") == "queued"
            if not force and same_source and latest["config_fingerprint"] == config.processing_fingerprint:
                if latest_result is not None and latest_result["error"] is None:
                    return latest_result
                if latest["state"] == "pending" and (latest_queued or latest["lease_expires_at"] > now):
                    raise ClaimBusy(json.loads(latest["claim_json"]))
            abandoned_id = None
            if latest is not None and latest["state"] == "pending" and (latest_queued or latest["lease_expires_at"] <= now):
                abandoned_id = latest["attempt_id"]
                db.execute("UPDATE attempts SET state='abandoned' WHERE attempt_id=?", (latest["attempt_id"],))
                db.execute("INSERT INTO attempt_events(attempt_id,event,recorded_at) VALUES(?,?,?)", (latest["attempt_id"], "abandoned", now))
            routing_only = bool(
                not force and same_source and latest_result is not None
                and latest_result["error"] is None
                and latest_result["extraction_fingerprint"] == config.extraction_fingerprint
            )
            attempt_id = uuid4().hex
            token = db.execute(
                "SELECT COALESCE(MAX(fencing_token),0)+1 FROM attempts WHERE document_id=?", (document_id,),
            ).fetchone()[0]
            claim = {
                "attempt_id": attempt_id, "document_id": document_id,
                "source_sha256": source_hash, "source_revision": revision,
                "ingestion_sequence": source_sequence, "state": "pending",
                "operator": operator, "lease_owner": operator,
                "lease_expires_at": 0.0 if queued else now + lease_seconds, "fencing_token": token,
                "created_at": now, "attempt_kind": "routing" if routing_only else "extraction",
                "extraction_attempt_id": latest_result["extraction_attempt_id"] if routing_only else attempt_id,
                "routing_attempt_id": attempt_id,
                **{key: snapshot[key] for key in (
                    "model_configuration", "extraction_fingerprint", "processing_fingerprint",
                    "prompt_sha256", "schema_sha256", "policy_sha256",
                )},
            }
            if queued:
                claim["service_state"] = "queued"
            if abandoned_id is not None:
                claim["replaces_attempt_id"] = abandoned_id
            db.execute(
                "INSERT INTO attempts(attempt_id,document_id,source_sequence,config_fingerprint,state,lease_owner,lease_expires_at,fencing_token,claim_json) "
                "VALUES(?,?,?,?,?,?,?,?,?)",
                (attempt_id, document_id, source_sequence, config.processing_fingerprint, "pending", operator, claim["lease_expires_at"], token, _json(claim)),
            )
            db.execute(
                "INSERT INTO documents(document_id,source_sequence,latest_attempt_id) VALUES(?,?,?) "
                "ON CONFLICT(document_id) DO UPDATE SET source_sequence=excluded.source_sequence,latest_attempt_id=excluded.latest_attempt_id",
                (document_id, source_sequence, attempt_id),
            )
            db.execute("INSERT INTO attempt_events(attempt_id,event,recorded_at) VALUES(?,?,?)", (attempt_id, "claimed", now))
            if abandoned_id is not None and expected_attempt_id is not None:
                db.execute("INSERT INTO attempt_events(attempt_id,event,recorded_at) VALUES(?,?,?)", (attempt_id, "reclaimed", now))
        return claim

    def activate_claim(
        self, claim: dict[str, Any], *, operator: str, lease_seconds: float,
        execution: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Atomically take a queued item; active ownership is never stolen."""
        if not operator.strip() or not math.isfinite(lease_seconds) or lease_seconds <= 0:
            raise ValueError("A positive lease and named operator are required")
        with self._transaction() as db:
            row = self._attempt(claim["attempt_id"])
            if row["state"] == "completed":
                return json.loads(row["result_json"])
            saved = json.loads(row["claim_json"])
            if row["state"] != "pending":
                raise StaleClaimError("Queued item was abandoned")
            if saved.get("service_state") != "queued":
                raise ClaimBusy(saved)
            latest = db.execute("SELECT latest_attempt_id FROM documents WHERE document_id=?", (row["document_id"],)).fetchone()[0]
            if latest != row["attempt_id"]:
                raise StaleClaimError("Queued item was superseded")
            saved.update(
                operator=operator, lease_owner=operator, lease_expires_at=self._clock() + lease_seconds,
                fencing_token=REDACTED + 1, service_state="processing",
            )
            if execution is not None:
                saved["execution"] = execution
            db.execute(
                "UPDATE attempts SET lease_owner=?,lease_expires_at=?,fencing_token=REDACTED,claim_json=? WHERE attempt_id=?",
                (operator, saved["lease_expires_at"], saved["fencing_token"], _json(saved), row["attempt_id"]),
            )
            db.execute("INSERT INTO attempt_events(attempt_id,event,recorded_at) VALUES(?,?,?)", (row["attempt_id"], "started", self._clock()))
        return saved

    def renew_claim(self, claim: dict[str, Any], *, lease_seconds: float = 300) -> dict[str, Any]:
        if not math.isfinite(lease_seconds) or lease_seconds <= 0:
            raise ValueError("lease_seconds must be finite and positive")
        with self._transaction() as db:
            row = self._check_claim(claim)
            if row["state"] != "pending":
                raise StaleClaimError("Completed claims cannot be renewed")
            saved = json.loads(row["claim_json"])
            saved["lease_expires_at"] = max(row["lease_expires_at"], self._clock() + lease_seconds)
            db.execute(
                "UPDATE attempts SET lease_expires_at=?,claim_json=? WHERE attempt_id=?",
                (saved["lease_expires_at"], _json(saved), row["attempt_id"]),
            )
            db.execute("INSERT INTO attempt_events(attempt_id,event,recorded_at) VALUES(?,?,?)", (row["attempt_id"], "renewed", self._clock()))
        return saved

    def note_retry(self, claim: dict[str, Any], category: str, attempt: int, delay: float) -> None:
        if category not in {"rate-limit", "timeout", "unavailable"}:
            raise ValueError("Unsupported retry state")
        with self._transaction() as db:
            row = self._check_claim(claim)
            if row["state"] != "pending":
                raise StaleClaimError("Completed claims cannot report retries")
            saved = json.loads(row["claim_json"])
            saved.update(service_state=category, retry_attempt=attempt, retry_delay=delay, next_retry_at=self._clock() + delay)
            db.execute("UPDATE attempts SET claim_json=? WHERE attempt_id=?", (_json(saved), row["attempt_id"]))

    def recovery_candidates(self, *, retry_errors: bool = False) -> list[dict[str, Any]]:
        rows = self._connection.execute(
            "SELECT a.* FROM attempts a JOIN documents d ON d.latest_attempt_id=a.attempt_id ORDER BY a.sequence"
        ).fetchall()
        candidates = []
        for row in rows:
            if row["state"] == "pending":
                claim = json.loads(row["claim_json"])
                if claim.get("service_state") == "queued" or row["lease_expires_at"] <= self._clock():
                    candidates.append(claim)
            elif retry_errors and row["state"] == "completed":
                result = json.loads(row["result_json"])
                if result["error"] is not None:
                    candidates.append(result)
        return candidates

    def recover_claim(self, candidate: dict[str, Any], *, operator: str, lease_seconds: float) -> dict[str, Any]:
        """Recover only the latest expired/failed attempt using saved bytes."""
        row = self._attempt(candidate["attempt_id"])
        if row["state"] == "pending":
            saved = json.loads(row["claim_json"])
            if saved.get("service_state") == "queued":
                return saved
            if row["lease_expires_at"] > self._clock():
                raise ClaimBusy(saved)
        elif row["state"] != "completed" or json.loads(row["result_json"])["error"] is None:
            raise StaleClaimError("Attempt is not recoverable")
        source = self._source_row(row["attempt_id"])
        snapshot = self.configuration(row["attempt_id"])
        return self._claim_bytes(
            source["original_bytes"], document_id=row["document_id"], config=ProcessingConfig(_json(snapshot)),
            operator=operator, lease_seconds=lease_seconds, force=row["state"] == "completed",
            queued=True, expected_attempt_id=row["attempt_id"],
        )

    def _check_claim(self, claim: dict[str, Any]) -> sqlite3.Row:
        row = self._attempt(claim["attempt_id"])
        if row["fencing_token"] != claim["fencing_token"] or row["lease_owner"] != claim["lease_owner"]:
            raise StaleClaimError("Claim owner or fencing token no longer matches")
        if row["state"] == "completed":
            return row
        if row["state"] != "pending" or row["lease_expires_at"] <= self._clock():
            raise StaleClaimError("Claim has expired or was abandoned")
        return row

    def run_claim(self, claim: dict[str, Any], *, provider: Provider) -> dict[str, Any]:
        row = self._check_claim(claim)
        if row["state"] == "completed":
            return json.loads(row["result_json"])
        # Trust durable metadata, never a caller-mutated claim dictionary.
        metadata = json.loads(row["claim_json"])
        snapshot = self.configuration(row["attempt_id"])
        if provider.provider_kind != snapshot["provider_kind"]:
            raise ValueError("Runtime provider kind does not match the saved configuration")
        runtime = provider.with_snapshot(snapshot) if provider.provider_kind == "http" else provider
        policy = review.ReviewPolicy.from_text(snapshot["policy_text"])
        raw_extraction = None
        try:
            source = self.source(row["attempt_id"])
            if metadata["attempt_kind"] == "routing":
                original = self._attempt(metadata["extraction_attempt_id"])
                raw_extraction = json.loads(original["raw_extraction_json"])
                original_result = json.loads(original["result_json"])
                extracted = ExtractionRecord(source.document_id, source.source_sha256, raw_extraction, original_result["response_source"])
            else:
                extracted = extract_source(source, provider=runtime, schema_text=snapshot["schema_text"])
                raw_extraction = extracted.extraction
            result = asdict(review.route_extraction(extracted, source=source, policy=policy))
        except ExtractionError as exc:
            result = asdict(_failure(metadata["document_id"], metadata["source_sha256"], exc.category, runtime))
        with self._transaction() as db:
            latest = self._check_claim(claim)
            if latest["state"] == "completed":
                return json.loads(latest["result_json"])
            metadata = json.loads(latest["claim_json"])
            completed = {**metadata, **result, "state": "completed", "completed_at": self._clock()}
            if "service_state" in completed:
                completed["service_state"] = "completed" if result["error"] is None else result["error_category"]
            db.execute(
                "UPDATE attempts SET state='completed',result_json=?,raw_extraction_json=? WHERE attempt_id=?",
                (_json(completed), None if raw_extraction is None else _json(raw_extraction), row["attempt_id"]),
            )
            db.execute(
                "UPDATE documents SET current_attempt_id=? WHERE document_id=? AND latest_attempt_id=?",
                (row["attempt_id"], metadata["document_id"], row["attempt_id"]),
            )
            db.execute("INSERT INTO attempt_events(attempt_id,event,recorded_at) VALUES(?,?,?)", (row["attempt_id"], "completed", completed["completed_at"]))
        return completed

    def intake(
        self, paths: Iterable[Path], *, provider: Provider, config: ProcessingConfig,
        operator: str, force: bool = False, lease_seconds: float = 300,
    ) -> list[dict[str, Any]]:
        results = []
        for path in paths:
            try:
                claim = self.claim(path, config=config, operator=operator, force=force, lease_seconds=lease_seconds)
            except ClaimBusy as exc:
                results.append(exc.claim)
                continue
            results.append(claim if claim["state"] == "completed" else self.run_claim(claim, provider=provider))
        return results
# IT access-request intake

Python 3.11+ application being built in the order in `planning/plan.md`.
Steps 1–6 provide scripted and HTTP providers, extraction validation, ordered
routing for human review, explicit failure records, durable SQLite state,
bounded workers and coordinated recovery. The operator CLI and consistent
file exports are step 7 work.

Setup requires Python 3.11+ with the `venv` module and system pip 22.3+.
From the repository root:

```bash
python3 -m venv --without-pip .venv
python3 -m pip --python .venv install -r requirements.lock
. .venv/bin/activate
env -u API_KEY python3 -m unittest discover -s tests -v
```

The environment is created without its own pip so this also works on systems
where `ensurepip` is unavailable. The system pip installs the pinned runtime
dependencies into `.venv`. Installation requires package access or a prepared
offline package source; the tests themselves use saved mock responses, block
network connections and forbid reading `API_KEY`.

`intake.providers.ScriptedProvider` consumes saved reply/error fixtures with
optional event barriers for deterministic delays. `intake.extraction.read_export`
preserves the original bytes, SHA-256 and filename and decodes the UTF-8 JSON
message. `intake.extraction.extract_file(path, provider=provider)` passes only
that message to the provider and returns an extraction after validating the
completion envelope, the supplied `snapshot.schema.json` and literal supporting
quotes. Invalid input or output raises a classified `ExtractionError`.

`intake.prompts.build_messages(message=message)` combines the versioned
`intake/extraction-prompt.txt` instructions and supplied schema in the system
role, keeping source text in a separate user message. The HTTP adapter uses
this builder; scripted replies do not perform semantic extraction.

`intake.review.review_file(path, provider=provider)` validates the extraction,
then applies the office policy in order: inspect instruction overrides, confirm
identified dated withdrawals, clarify incomplete or conflicting requests,
review production/write/admin risks, and review complete staging/read requests.
It preserves scalar facts and adds issues for missing facts, identifier
mismatches, invalid dates and reversed access ranges. Extraction and routing
share the same source snapshot. A named manager never supplies approval.

The source override check uses finite text patterns alongside provider-reported
override issues. The mock tests exercise the supplied override and its variant;
they do not establish detection of every possible instruction attack. Other
unresolved extraction issues conservatively require clarification after the
override and withdrawal rules. This lower-level review API propagates
`ExtractionError`; `intake.processing.process_file` converts it to an error
record with null extraction, category, source identity and retry instructions.
`process_files` continues after a failed document. This service is sequential
and stateless; the `StateStore` API below adds durable attempts. Unreadable files
have no source hash; malformed readable exports retain the hash of their
original bytes.

`intake.state.StateStore` uses SQLite WAL on one local host and local filesystem.
It stores original source bytes, document revisions, ingestion sequence,
configuration snapshots, operator identity and completed attempts. Sources,
configuration snapshots, events and completed attempts are retained with
database triggers preventing updates/deletes. Current pointers and pending
claims are stored separately. Provider calls run outside write transactions.

For persistent mock intake from the repository root, after activating `.venv`:

```python
from pathlib import Path
from intake.providers import ScriptedProvider
from intake.state import ProcessingConfig, StateStore

provider = ScriptedProvider(mock_dir=Path("tests/mock_responses"), script=[
    {"reply": "complete-001.json"}, {"reply": "complete-002.json"},
])
config = ProcessingConfig.capture(
    provider=provider, policy_path=Path("materials/office-policy.md"),
)
with StateStore(Path("state/intake.sqlite3")) as store:
    records = store.intake(
        [Path("materials/requests/IT-001.json"), Path("materials/requests/IT-002.json")],
        provider=provider, config=config, operator="operator-a",
    )
    print([(record["document_id"], record["status"]) for record in records])
    print(store.pending())
```

An unchanged success reuses its original attempt without another provider call,
including after reopening the database. Changes to original bytes create a new
source revision; byte-format-only changes count. New source/model/generation/
prompt/schema settings create an extraction attempt. `force=True` bypasses
success reuse; a failed retry becomes current and retains the earlier success
in history. A regular rerun after failure creates another attempt. Later
incremental batches preserve documents absent from that batch, and filenames
remain independent even when messages state the same request ID.

A policy-only refresh reuses the original validated extraction and creates a
routing attempt linked by `extraction_attempt_id` and `routing_attempt_id`.
The supported policy template permits destination edits to the supplied five
review rules; changed conditions/order require routing-code and test changes.
Extraction rules remain in the versioned extraction prompt, so changes to
those rules require updating that prompt and its tests. Policy text alone is
not an executable language for arbitrary new business rules.

`store.current()` returns the current completed result per document.
`store.history(document_id)` returns all completed attempts in acceptance
order, including the current one. `store.pending()` returns unfinished claims
with source/configuration identity, lease owner/expiry and fencing token.
`store.source(attempt_id)` and `store.configuration(attempt_id)` retrieve saved
source and configuration snapshots. Claims and completion commits are separate;
`store.run_claim(claim, provider=provider)` uses saved bytes, prompt/schema,
settings and policy even if their files have subsequently changed or vanished.

State intake requires readable files to accept a durable source revision;
malformed readable exports can be retained as error attempts. Direct
`StateStore.intake` remains sequential. Use `intake.workers.run_intake` for
bounded parallel processing and `intake.workers.resume` for recovery. Both
accept a database path, `provider_factory`, operator name, `max_workers`,
lease duration and optional heartbeat interval. `run_intake` also accepts input
paths and the captured `ProcessingConfig`. Runtime worker limits are recorded
in each started attempt's `execution` metadata.

For parallel processing with the pinned HTTP configuration:

```python
import json
from pathlib import Path
from intake.http_provider import HttpProvider, ProviderSettings
from intake.state import ProcessingConfig
from intake.workers import run_intake, resume

settings = ProviderSettings(**json.loads(Path("config/provider.json").read_text()))
provider = HttpProvider(settings=settings)
config = ProcessingConfig.capture(
    provider=provider, policy_path=Path("materials/office-policy.md"),
)
run_intake(
    Path("state/intake.sqlite3"), sorted(Path("materials/requests").glob("*.json")),
    provider_factory=lambda: HttpProvider(settings=settings), config=config,
    operator="regional-operator-a", max_workers=4,
)
# After an interruption, using the same runtime provider kind:
resume(
    Path("state/intake.sqlite3"), provider_factory=lambda: HttpProvider(settings=settings),
    operator="regional-operator-b", max_workers=4,
)
```

This example makes real provider requests using `API_KEY`. Acceptance tests
instead supply fixture providers or injected HTTP transports. Each provider
factory should return a provider safe for its worker; HTTP providers restore
the model/settings and prompt/schema from the attempt snapshot during resume.

Accepted sources are committed to a durable queue before workers start.
Queued work has no active lease; activation atomically assigns an owner, expiry
and fencing token. Calls default to four workers per operator, configurable
from 1 to 32. Each active call renews its 300-second lease every five seconds
by default, using a separate SQLite connection. Choose a heartbeat interval
shorter than the lease. The shared host clock determines lease expiry.

Two operators can start the same intake: valid active claims are skipped,
completed successes are reused, and queued work is taken once. Concurrency is
bounded per operator; there is no central requests-per-second quota across
operators. HTTP rate limits use the bounded per-call retry/backoff mechanism.
`pending()` exposes `queued`, `processing`, `rate-limit`, `timeout` or
`unavailable` service states with retry timing where applicable. Completed
extraction errors remain visible in `current()` with actionable retry guidance.

Pass a `threading.Event` as `stop_event` for a graceful stop: accepted queued
sources stay durable, no new calls start after the stop is observed, and
in-flight calls drain. An optional `on_result` callback runs after a result is
committed so operators can observe progress while other calls are pending.
After a forced process interruption, resume starts queued work and reclaims
expired active leases from saved source/configuration bytes. It does not steal
a live lease or reprocess completed successes. Use `retry_errors=True` to also
retry latest completed errors. Original files need not still exist.

`store.events(document_id)` preserves claim, start, renewal, abandonment,
reclamation and completion events. A reclaimed worker's old fencing token
cannot publish or renew. A late completion of an older source revision can
remain in history while the current pointer keeps the newer accepted result.
Result publication and the current-pointer update commit together; interruption
before commit leaves pending work, and interruption after commit preserves the
whole result.

The operating context is 200–400 messages daily and roughly 2,000 during a
burst, on one host with a shared local SQLite database. T37–T40 exercise delayed
calls, visible backoff, two actual operator processes, forced worker termination,
crashes around commit, lease recovery, stale workers and source revision races.
The mock workload checks use 200, 400 and 2,000 authored withdrawals with four
workers, stop partway, delete the exports and resume from saved bytes. Each
check asserts one current result per document and preserves earlier completions.
These observed results use scripted fixtures and fake clocks; they establish
the tested state/recovery behavior, not live model accuracy, live service
throughput, hardware power-loss durability or multi-host/network-filesystem
support. CLI intake, pending and retry commands remain step 7 work.

The HTTP adapter implements non-streaming Chat Completions with strict JSON
Schema output. The pinned configuration in `config/provider.json` targets
`https://api.openai.com/v1` with `gpt-4o-mini-2024-07-18`, using temperature 0,
top_p 1 and max_tokens 2048. This request format and model snapshot are described
in OpenAI's [Chat Completions reference](https://developers.openai.com/api/reference/resources/chat/subresources/completions/methods/create)
and [Structured Outputs guide](https://developers.openai.com/api/docs/guides/structured-outputs?api-mode=chat).
Endpoint, provider label, model, timeout, retry budget/delays and generation
parameters are configurable through `ProviderSettings` and the JSON file.
Only supported generation parameters are accepted; they cannot replace
messages, model or response format. The prompt version is recorded separately.

The real adapter reads its credential only from `API_KEY` when `complete` is
called. It does not store the credential in configuration or evidence. HTTP
redirects are rejected. Logs report document IDs, failure categories and retry
timing without upstream response bodies, raw exceptions, request headers or
credentials. Failure records use fixed category-specific guidance.

Each message gets its own bounded retry budget: at most three attempts by
default, configurable from 1 to 10. Timeouts, connection failures, rate limits
and server failures are retried with capped exponential delays. Numeric
Retry-After values can increase the delay up to the configured cap; invalid or
date-form headers fall back to exponential delay. The default timeout is 30
seconds per socket operation, not an overall processing deadline. Refusal,
interruption, malformed JSON, schema/quote errors and ordinary HTTP client
errors require explicit operator retry. Retry strings reserve the CLI interface
planned for step 7; until then, rerun `process_file` using the same provider
settings. Successful records use `mock` or `provider/model` response provenance.

To construct the configured provider for the Python service:

```python
import json
from pathlib import Path
from intake.http_provider import HttpProvider, ProviderSettings

settings = ProviderSettings(**json.loads(Path("config/provider.json").read_text()))
provider = HttpProvider(settings=settings)
# process_file(path, provider=provider) makes real requests using API_KEY.
```

